118		if t.IsZero() {
119			return "never"
120		}
121		d := time.Since(t)
122		switch {
123		case d < time.Minute:
124			return "just now"
125		case d < time.Hour:
126			return fmt.Sprintf("%dm ago", int(d.Minutes()))
127		case d < 24*time.Hour:
